export TZ=UTC; date -u +%TZ
export CN=''
export HP=''
export LS=''
setsid nohup timeout 3600 srun --overlap --jobid 174134 -N1 -n1 env CUDA_VISIBLE_DEVICES= bash -c '
set -u; D=/tmp/a15_f10_174134; mkdir -p $D/b && cd $D
exec > $D/run.out 2>&1
date -u +%TZ; hostname
echo "$CN" | base64 -d > b/cn.py; echo "$HP" | base64 -d > h10.py; echo "$LS" | base64 -d > L10.sh
sha256sum b/cn.py h10.py L10.sh
M=/tmp/a15_dbg_174134/mixc.json; ls -la $M
python3 -I -c "import json,sys,shutil; s=json.load(open(sys.argv[1])); p=s[\"entry\"][\"order\"][\"path\"]; print(\"order\",p); shutil.copy(sys.argv[1],\"mixc.json\"); shutil.copy(p,\"mixorder.json\")" $M
sha256sum mixc.json mixorder.json
for m in census plant prepare; do echo "== $m $(date -u +%TZ)"; A15_THREADS=4 nice -n 10 timeout 2400 bash L10.sh h10.py $D $m 2>&1 | grep -v -E "UserWarning|_cpu_device_warning|fast path" | cut -c1-3000 > log_$m.txt; echo "rc $m ${PIPESTATUS[0]} $(date -u +%TZ)"; done
echo ALLDONE; date -u +%TZ
' > /dev/null 2>&1 < /dev/null &
sleep 15; squeue -j 174134 -s -o "%i %j %T %M" | head; echo launched
